import React, { useState, useMemo } from 'react';
import { Trash2, Plus, Play, Clock, Calendar, Download, ShieldCheck, Globe, Home, BookOpen } from 'lucide-react';

// --- HELPER FUNCTIONS ---
const formatTime = (timeStr) => {
  if (!timeStr) return "";
  const [h, m] = timeStr.split(':').map(Number);
  const suffix = h >= 12 ? 'PM' : 'AM';
  const displayH = h % 12 || 12;
  return `${displayH}:${String(m).padStart(2, '0')} ${suffix}`;
};

const addHours = (time, hours) => {
  const [h, m] = time.split(':').map(Number);
  const totalH = h + hours;
  return `${String(totalH).padStart(2, '0')}:${String(m).padStart(2, '0')}`;
};

const DepartmentCard = ({ dept, onUpdate, onGenerate, globalSchedule = [], allDepartments = [] }) => {
  const [activeTab, setActiveTab] = useState("subjects");
  const [localPreview, setLocalPreview] = useState([]);
  const { subjects, proctors, rooms, name: deptName, code: deptCode, id: deptId } = dept;

  // --- GENERATOR UI STATES ---
  const [examDays, setExamDays] = useState(0); 
  const [examDates, setExamDates] = useState([]);
  const [startTime, setStartTime] = useState("08:00");
  const [selectedYear, setSelectedYear] = useState("1");
  const [sectionCount, setSectionCount] = useState(0); 
  const [proctorSource, setProctorSource] = useState("Department");
  const [roomSource, setRoomSource] = useState("Department");

  // --- INPUT STATES ---
  const [pName, setPName] = useState("");
  const [pDayStart, setPDayStart] = useState("");
  const [pDayEnd, setPDayEnd] = useState("");
  const [pTimeStart, setPTimeStart] = useState("08:00");
  const [pTimeEnd, setPTimeEnd] = useState("17:00");
  const [roomNum, setRoomNum] = useState("");
  const [roomType, setRoomType] = useState("Department");

  // --- POOLS ---
  const globalProctorPool = useMemo(() => allDepartments.flatMap(d => d.proctors), [allDepartments]);
  const globalRoomPool = useMemo(() => allDepartments.flatMap(d => d.rooms), [allDepartments]);

  const handleExamDayChange = (val) => {
    const num = parseInt(val) || 0;
    setExamDays(num);
    setExamDates(new Array(num).fill(''));
  };

  const exportToExcel = () => {
    if (localPreview.length === 0) return alert("Generate a schedule first!");
    const headers = "Day,Section,Date,Window,Room,Proctor,Subject Breakdown\n";
    const rows = localPreview.map(row => 
      `${row.day},${row.section},${row.date},"${row.time}",${row.room},${row.proctor},"${row.subs.map(s => `${s.code} (${s.slot})`).join(' | ')}"`
    ).join("\n");

    const blob = new Blob([headers + rows], { type: 'text/csv' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `${deptCode}_Year${selectedYear}_Preview.csv`;
    link.click();
  };

  const handleGenerateClick = () => {
    const yearSubs = subjects[selectedYear] || [];
    if (yearSubs.length === 0) return alert("No subjects found!");
    if (examDays === 0 || sectionCount === 0) return alert("Complete configuration first!");
    if (examDates.some(d => !d)) return alert("Fill all dates!");

    const shuffled = [...yearSubs].sort(() => Math.random() - 0.5);
    const dailySubs = Array.from({ length: examDays }, () => []);
    shuffled.forEach((s, i) => dailySubs[i % examDays].push(s));

    const finalGeneratedData = [];
    const previewData = [];

    for (let d = 0; d < examDays; d++) {
      const dayDate = examDates[d];
      const daySubjects = dailySubs[d];
      const duration = daySubjects.length;
      const endTime = addHours(startTime, duration);

      const isRoomFree = (rNum) => !globalSchedule.some(gs => gs.room === rNum && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time));
      const localRooms = rooms.filter(r => isRoomFree(r.number));
      const otherRooms = globalRoomPool.filter(r => !rooms.find(dr => dr.number === r.number) && isRoomFree(r.number));
      let availableRooms = roomSource === "Department" ? [...localRooms, ...otherRooms] : [...otherRooms, ...localRooms];
      availableRooms.sort((a,b) => a.number.localeCompare(b.number, undefined, {numeric: true}));

      let dayUsedProctors = [];

      for (let s = 0; s < sectionCount; s++) {
        const sectionID = `${deptCode}${selectedYear}${String.fromCharCode(65 + s)}`;
        const selectedRoom = availableRooms[s];
        if (!selectedRoom) return alert(`Room depletion on Day ${d+1}`);

        const checkProctor = (pool) => pool.find(p => 
            dayDate >= p.dayStart && dayDate <= p.dayEnd &&
            startTime >= p.timeStart && endTime <= p.timeEnd &&
            !dayUsedProctors.includes(p.name) &&
            !globalSchedule.some(gs => gs.proctor === p.name && gs.exam_date === dayDate && (startTime < gs.end_time && endTime > gs.start_time))
        );

        let selectedProctor = checkProctor(proctorSource === "Department" ? proctors : globalProctorPool);
        if (!selectedProctor && proctorSource === "Department") selectedProctor = checkProctor(globalProctorPool);
        if (!selectedProctor) return alert(`Staff depletion on Day ${d+1}`);

        dayUsedProctors.push(selectedProctor.name);

        // Map subjects to specific time slots for preview
        const subjectSlots = daySubjects.map((sub, idx) => ({
            code: sub.code,
            name: sub.name,
            slot: `${formatTime(addHours(startTime, idx))} - ${formatTime(addHours(startTime, idx + 1))}`
        }));

        previewData.push({
          day: d + 1, section: sectionID, date: dayDate,
          time: `${formatTime(startTime)} - ${formatTime(endTime)}`,
          room: selectedRoom.number, proctor: selectedProctor.name,
          subs: subjectSlots
        });

        daySubjects.forEach((sub, idx) => {
          finalGeneratedData.push({
            subject_code: sub.code, subject_name: sub.name, section: sectionID,
            year_level: selectedYear, dept_code: deptCode, exam_date: dayDate,
            start_time: addHours(startTime, idx), end_time: addHours(startTime, idx + 1),
            room: selectedRoom.number, proctor: selectedProctor.name
          });
        });
      }
    }

    setLocalPreview(previewData);
    onGenerate(finalGeneratedData, examDates);
    setActiveTab("preview");
  };

  return (
    <div className="bg-white rounded-[3rem] shadow-2xl border border-slate-200 overflow-hidden mb-12">
      <div className="bg-slate-900 p-8 text-white flex justify-between items-center border-b-4 border-blue-600">
        <h2 className="text-3xl font-black uppercase italic">{deptName}</h2>
        <div className="bg-blue-600/20 border border-blue-500/50 px-4 py-2 rounded-2xl">
            <span className="text-[10px] font-black uppercase text-blue-400 block">Department Code</span>
            <span className="text-xl font-black uppercase">{deptCode}</span>
        </div>
      </div>

      <div className="flex bg-slate-50 p-2 border-b">
        {['subjects', 'proctors', 'rooms', 'generate', 'preview'].map(t => (
          <button key={t} onClick={() => setActiveTab(t)} className={`flex-1 py-4 text-[10px] font-black uppercase tracking-widest rounded-xl transition-all ${activeTab === t ? 'bg-white shadow-lg text-blue-600' : 'text-slate-400'}`}>
            {t}
          </button>
        ))}
      </div>

      <div className="p-10">
        {/* --- GENERATE TAB --- */}
        {activeTab === 'generate' && (
          <div className="bg-slate-900 rounded-[3rem] p-12 text-white space-y-10">
            <div className="grid grid-cols-1 md:grid-cols-2 gap-12">
              <div className="space-y-6">
                <h4 className="text-blue-400 font-black text-[10px] uppercase tracking-widest flex items-center gap-2"><Calendar size={14}/> Timeline</h4>
                <input type="number" value={examDays || ''} onChange={e => handleExamDayChange(e.target.value)} placeholder="Days Count" className="w-full bg-slate-800 p-4 rounded-2xl text-xl font-black text-blue-400 border-none" />
                <div className="space-y-2 max-h-40 overflow-y-auto pr-2">
                    {examDates.map((d, i) => (
                      <div key={i} className="flex items-center gap-3 bg-slate-800 p-3 rounded-xl border border-slate-700">
                        <span className="text-blue-500 font-black text-[10px] w-12">DAY {i+1}</span>
                        <input type="date" value={d} onChange={e => { const updated = [...examDates]; updated[i] = e.target.value; setExamDates(updated); }} className="w-full bg-transparent text-xs font-bold outline-none text-white" />
                      </div>
                    ))}
                </div>
                <input type="time" value={startTime} onChange={e => setStartTime(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl font-black text-blue-400 border-none" />
              </div>

              <div className="space-y-6">
                <h4 className="text-emerald-400 font-black text-[10px] uppercase tracking-widest flex items-center gap-2"><ShieldCheck size={14}/> Parameters</h4>
                <div className="grid grid-cols-2 gap-4">
                    <select value={selectedYear} onChange={e => setSelectedYear(e.target.value)} className="w-full bg-slate-800 p-4 rounded-2xl font-black text-xs text-blue-400 border-none outline-none">
                        {[1, 2, 3, 4, 5].map(y => <option key={y} value={y}>Year Level {y}</option>)}
                    </select>
                    <input type="number" value={sectionCount || ''} onChange={e => setSectionCount(parseInt(e.target.value) || 0)} placeholder="Sections" className="w-full bg-slate-800 p-4 rounded-2xl font-black text-emerald-400 border-none" />
                </div>
                <div className="grid grid-cols-1 gap-3">
                    <button onClick={() => setProctorSource(proctorSource === "Department" ? "Global" : "Department")} className="bg-slate-800 p-4 rounded-xl text-[10px] font-black uppercase flex justify-between items-center border border-slate-700">
                        <span>Staff: {proctorSource}</span>
                        {proctorSource === "Department" ? <Home size={14}/> : <Globe size={14}/>}
                    </button>
                    <button onClick={() => setRoomSource(roomSource === "Department" ? "Global" : "Department")} className="bg-slate-800 p-4 rounded-xl text-[10px] font-black uppercase flex justify-between items-center border border-slate-700">
                         <span>Rooms: {roomSource}</span>
                         {roomSource === "Department" ? <Home size={14}/> : <Globe size={14}/>}
                    </button>
                </div>
                <button onClick={handleGenerateClick} className="w-full bg-blue-600 py-8 rounded-[2rem] font-black uppercase tracking-[0.3em] flex items-center justify-center gap-4 hover:bg-blue-500 transition-all shadow-2xl active:scale-95">
                  <Play size={24} fill="currentColor" /> Generate Block Schedule
                </button>
              </div>
            </div>
          </div>
        )}

        {/* --- ENHANCED PREVIEW TAB --- */}
        {activeTab === 'preview' && (
          <div className="space-y-8 animate-in fade-in duration-500">
            <div className="flex justify-between items-center">
              <h3 className="text-2xl font-black uppercase text-slate-800 tracking-tighter">Year {selectedYear} Draft Schedule</h3>
              <button onClick={exportToExcel} className="flex items-center gap-2 bg-emerald-600 text-white px-6 py-3 rounded-xl font-black text-[10px] uppercase shadow-lg hover:bg-emerald-700">
                <Download size={16} /> Export CSV
              </button>
            </div>

            <div className="grid grid-cols-1 gap-6">
                {localPreview.length > 0 ? localPreview.map((row, i) => (
                    <div key={i} className="bg-white border-2 border-slate-100 rounded-[2.5rem] overflow-hidden flex flex-col md:flex-row hover:border-blue-200 transition-colors shadow-sm">
                        {/* Summary Column */}
                        <div className="bg-slate-50 p-8 md:w-72 flex flex-col justify-between border-r border-slate-100">
                            <div>
                                <span className="text-blue-600 font-black text-[10px] uppercase tracking-widest">Section</span>
                                <h5 className="text-3xl font-black text-slate-900">{row.section}</h5>
                            </div>
                            <div className="mt-6 space-y-2">
                                <p className="text-[10px] font-black text-slate-400 uppercase flex items-center gap-2"><Calendar size={12}/> {row.date}</p>
                                <p className="text-[10px] font-black text-slate-400 uppercase flex items-center gap-2"><Clock size={12}/> {row.time}</p>
                            </div>
                            <div className="mt-6 pt-6 border-t border-slate-200 flex flex-wrap gap-2">
                                <span className="bg-white px-3 py-1 rounded-lg border text-[10px] font-black">ROOM {row.room}</span>
                                <span className="bg-white px-3 py-1 rounded-lg border text-[10px] font-black uppercase">STAFF: {row.proctor.split(' ')[0]}</span>
                            </div>
                        </div>

                        {/* Subjects Sequence Column */}
                        <div className="flex-1 p-8">
                            <div className="flex items-center gap-2 mb-6">
                                <BookOpen size={16} className="text-blue-500" />
                                <span className="text-[10px] font-black uppercase tracking-widest text-slate-400">Sequence breakdown</span>
                            </div>
                            <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                {row.subs.map((s, idx) => (
                                    <div key={idx} className="bg-slate-50 p-4 rounded-2xl border border-transparent hover:border-blue-100 transition-all group">
                                        <div className="flex justify-between items-start mb-1">
                                            <span className="text-xs font-black text-blue-600 group-hover:scale-105 transition-transform">{s.code}</span>
                                            <span className="text-[9px] font-black text-slate-400 uppercase italic">{s.slot}</span>
                                        </div>
                                        <p className="text-[10px] font-bold text-slate-500 uppercase truncate">{s.name}</p>
                                    </div>
                                ))}
                            </div>
                        </div>
                    </div>
                )) : (
                    <div className="text-center py-20 bg-slate-50 rounded-[3rem] border-2 border-dashed border-slate-200">
                        <p className="text-slate-400 font-black uppercase tracking-widest text-sm">No Blocks Generated</p>
                    </div>
                )}
            </div>
          </div>
        )}

        {/* --- SUBJECTS TAB --- */}
        {activeTab === 'subjects' && (
          <div className="space-y-4">
            <div className="grid grid-cols-4 gap-4 bg-slate-50 p-6 rounded-[2rem]">
              <select className="p-3 rounded-xl text-xs font-bold bg-white border-none shadow-sm" value={selectedYear} onChange={(e) => setSelectedYear(e.target.value)}>
                {[1, 2, 3, 4, 5].map(y => <option key={y} value={y}>Year Level {y}</option>)}
              </select>
              <input id={`sC-${deptId}`} placeholder="CODE" className="p-3 rounded-xl text-xs font-bold border-none shadow-inner" />
              <input id={`sN-${deptId}`} placeholder="NAME" className="p-3 rounded-xl text-xs font-bold border-none shadow-inner" />
              <button onClick={() => {
                const c = document.getElementById(`sC-${deptId}`).value;
                const n = document.getElementById(`sN-${deptId}`).value;
                if (c && n) {
                  onUpdate('subjects', { ...subjects, [selectedYear]: [...(subjects[selectedYear] || []), { code: c.toUpperCase(), name: n }] });
                  document.getElementById(`sC-${deptId}`).value = '';
                  document.getElementById(`sN-${deptId}`).value = '';
                }
              }} className="bg-blue-600 text-white rounded-xl font-black uppercase text-[10px] shadow-lg">Add Subject</button>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {subjects[selectedYear]?.map((s, i) => (
                <div key={i} className="flex justify-between p-5 bg-white border-2 border-slate-50 rounded-2xl items-center font-black text-xs hover:border-blue-100 transition-colors">
                  <span className="text-blue-600">{s.code}</span> <span className="text-slate-400 ml-2">{s.name}</span>
                  <button onClick={() => onUpdate('subjects', { ...subjects, [selectedYear]: subjects[selectedYear].filter((_, idx) => idx !== i) })}><Trash2 size={16} className="text-slate-200 hover:text-rose-500" /></button>
                </div>
              ))}
            </div>
          </div>
        )}

        {/* --- PROCTORS TAB --- */}
        {activeTab === 'proctors' && (
          <div className="space-y-8">
            <div className="bg-emerald-50 p-8 rounded-[2.5rem] border border-emerald-100 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <input value={pName} onChange={e => setPName(e.target.value)} placeholder="INSTRUCTOR FULL NAME" className="p-4 rounded-2xl text-xs font-bold border-none shadow-sm" />
                <button onClick={() => {
                  if (pName && pDayStart && pDayEnd && pTimeStart && pTimeEnd) {
                    onUpdate('proctors', [...proctors, { id: Date.now(), name: pName.toUpperCase(), dayStart: pDayStart, dayEnd: pDayEnd, timeStart: pTimeStart, timeEnd: pTimeEnd }]);
                    setPName("");
                  }
                }} className="bg-emerald-600 text-white rounded-2xl font-black text-[10px] uppercase shadow-lg">Save Proctor Profile</button>
              </div>
              <div className="grid grid-cols-4 gap-4">
                <div className="space-y-1"><label className="text-[9px] font-black uppercase text-emerald-600 ml-2">Start Date</label><input type="date" value={pDayStart} onChange={e => setPDayStart(e.target.value)} className="w-full p-2 rounded-lg text-[10px] border-none" /></div>
                <div className="space-y-1"><label className="text-[9px] font-black uppercase text-emerald-600 ml-2">End Date</label><input type="date" value={pDayEnd} onChange={e => setPDayEnd(e.target.value)} className="w-full p-2 rounded-lg text-[10px] border-none" /></div>
                <div className="space-y-1"><label className="text-[9px] font-black uppercase text-emerald-600 ml-2">Shift Start</label><input type="time" value={pTimeStart} onChange={e => setPTimeStart(e.target.value)} className="w-full p-2 rounded-lg text-[10px] border-none" /></div>
                <div className="space-y-1"><label className="text-[9px] font-black uppercase text-emerald-600 ml-2">Shift End</label><input type="time" value={pTimeEnd} onChange={e => setPTimeEnd(e.target.value)} className="w-full p-2 rounded-lg text-[10px] border-none" /></div>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-4">
              {proctors.map(p => (
                <div key={p.id} className="p-5 border-2 border-slate-50 rounded-[2rem] flex justify-between items-center bg-white shadow-sm">
                  <div>
                    <p className="font-black text-xs uppercase text-slate-800">{p.name}</p>
                    <p className="text-[9px] text-slate-400 font-bold uppercase">{p.dayStart} — {p.dayEnd} | {formatTime(p.timeStart)} — {formatTime(p.timeEnd)}</p>
                  </div>
                  <Trash2 size={16} className="text-slate-200 hover:text-rose-500 cursor-pointer transition-colors" onClick={() => onUpdate('proctors', proctors.filter(item => item.id !== p.id))} />
                </div>
              ))}
            </div>
          </div>
        )}

        {/* --- ROOMS TAB --- */}
        {activeTab === 'rooms' && (
          <div className="space-y-8">
            <div className="flex gap-4 bg-amber-50 p-6 rounded-[2rem] border border-amber-100">
              <input value={roomNum} onChange={e => setRoomNum(e.target.value)} placeholder="ROOM NUMBER / NAME" className="flex-1 p-4 rounded-2xl text-sm font-black border-none shadow-sm" />
              <select value={roomType} onChange={e => setRoomType(e.target.value)} className="bg-white px-6 rounded-2xl font-black text-[10px] uppercase outline-none shadow-sm">
                <option value="Department">Internal</option>
                <option value="Global">Global</option>
              </select>
              <button onClick={() => { if (roomNum) { onUpdate('rooms', [...rooms, { id: Date.now(), number: roomNum.toUpperCase(), type: roomType }]); setRoomNum(""); } }} className="bg-amber-600 text-white px-8 rounded-2xl font-black uppercase text-[10px] shadow-lg">Assign Room</button>
            </div>
            <div className="grid grid-cols-4 md:grid-cols-6 gap-4">
              {rooms.map(r => (
                <div key={r.id} className="p-6 bg-white border-2 border-slate-50 rounded-[2.5rem] text-center relative group shadow-sm hover:border-amber-200 transition-colors">
                  <span className="font-black text-xl text-slate-800">{r.number}</span>
                  <span className={`block text-[8px] font-black uppercase mt-1 ${r.type === 'Global' ? 'text-blue-500' : 'text-amber-500'}`}>{r.type} Source</span>
                  <button className="absolute top-2 right-2 opacity-0 group-hover:opacity-100 text-rose-500 transition-opacity" onClick={() => onUpdate('rooms', rooms.filter(item => item.id !== r.id))}><Trash2 size={14}/></button>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default DepartmentCard;
